const API_BASE_URL = "http://localhost:8081/api"; // ✅ make sure this matches backend port

// --- Helper to get stored token ---
function getToken() {
  return localStorage.getItem("token");
}

// --- Helper: Parse JSON or plain text ---
async function parseResponse(response) {
  const text = await response.text();
  try {
    return JSON.parse(text); // ✅ valid JSON
  } catch {
    return { message: text }; // ✅ fallback to plain text
  }
}

// --- LOGIN ---
export async function login(email, password) {
  try {
    const response = await fetch(`${API_BASE_URL}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(errorText || "Login failed");
    }

    const data = await parseResponse(response); // ✅ safe parser
    if (data.token) {
      localStorage.setItem("token", data.token);
    }
    return data;
  } catch (error) {
    console.error("Login error:", error);
    throw error;
  }
}

// --- SIGNUP (also sends OTP) ---
export async function signup(data) {
  try {
    const userPayload = {
      username: data.username,
      email: data.email,
      passwordHash: data.password, // ✅ matches your backend entity
      firstName: "-",
      lastName: "-",
      phone: "-",
      role: "DEFAULT_USER",
    };

    const response = await fetch(`${API_BASE_URL}/users`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(userPayload),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(errorText || "Signup failed");
    }

    return await parseResponse(response); // ✅ safe parser
  } catch (error) {
    console.error("Signup error:", error);
    throw error;
  }
}

